#!/bin/sh
set -eu
python -c 'p="/app/app/trainer.py"; s=open(p).read(); s=s.replace("import json, os, random, torch", "import json, os, random, socket, torch"); s=s.replace("os.environ[\"MASTER_ADDR\"]=\"127.0.0.1\"; os.environ[\"MASTER_PORT\"]=str(29500 + (abs(hash(outdir)) % 900))", "os.environ[\"MASTER_ADDR\"]=\"127.0.0.1\"; os.environ[\"MASTER_PORT\"]=os.environ.get(\"FORGE_DDP_PORT\",\"29517\")"); a=s.index("    while global_step < target:"); b=s.index(chr(10)+"    if rank==0:",a); n="""    while global_step < target:\n        local_rows=data[sample_cursor:sample_cursor+cfg[\"accumulation_steps\"]]\n        count=torch.tensor([len(local_rows)],dtype=torch.int64)\n        dist.all_reduce(count,op=dist.ReduceOp.SUM)\n        total_samples=int(count.item())\n        if total_samples == 0: break\n        opt.zero_grad(set_to_none=True)\n        with ddp.no_sync():\n            for row in local_rows:\n                x=torch.tensor(row[0],dtype=torch.float32).unsqueeze(0); y=torch.tensor([row[1]])\n                (torch.nn.functional.cross_entropy(ddp(x),y,reduction=\"sum\")/total_samples).backward()\n        for param in ddp.parameters():\n            if param.grad is None:\n                param.grad=torch.zeros_like(param)\n            dist.all_reduce(param.grad,op=dist.ReduceOp.SUM)\n        opt.step(); global_step+=1; sample_cursor+=cfg[\"accumulation_steps\"]\n        if global_step==cfg[\"checkpoint_after_updates\"] and outdir:\n            if rank==0:\n                os.makedirs(outdir,exist_ok=True); torch.save({\"model\":ddp.module.state_dict(),\"optimizer\":opt.state_dict(),\"global_step\":global_step,\"sample_cursor\":sample_cursor},outdir+\"/checkpoint.pt\")\n            dist.barrier()\n"""; s=s[:a]+n+s[b:]; s=s.replace("cfg=config or _load_cfg(); mp.spawn", "cfg=config or _load_cfg(); sock=socket.socket(); sock.bind((\"127.0.0.1\",0)); os.environ[\"FORGE_DDP_PORT\"]=str(sock.getsockname()[1]); sock.close(); mp.spawn"); open(p,"w").write(s)'
